const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to evaluate ee.Objects as Promise
  const ev = (obj) =>
    new Promise((resolve, reject) => {
      obj.evaluate((res, err) => {
        if (err) reject(err);
        else resolve(res);
      });
    });

  // 1. Geometry & Time Definitions
  const lon = -70.647985;
  const lat = -34.752733;
  const region = ee.Geometry.Point([lon, lat]).buffer({distance: 20000}); // 20 km buffer

  const dates = ['2021-12-18', '2023-12-18'];

  async function buildImageForDate(dateStr) {
    const start = ee.Date(dateStr);
    const end = start.advance(1, 'day');

    const terraCol = ee.ImageCollection('MODIS/061/MOD10A1').filterDate(start, end);
    const aquaCol = ee.ImageCollection('MODIS/061/MYD10A1').filterDate(start, end);

    const terraSize = await ev(terraCol.size());
    const aquaSize = await ev(aquaCol.size());

    let img = null;
    let usedInfo = 'Same-day';
    if (terraSize === 0 && aquaSize === 0) {
      // Fallback: ±1 day window, choose nearest image among Terra/Aqua
      const wStart = start.advance(-1, 'day');
      const wEnd = end.advance(1, 'day');
      const altCol = ee.ImageCollection('MODIS/061/MOD10A1')
        .filterDate(wStart, wEnd)
        .merge(ee.ImageCollection('MODIS/061/MYD10A1').filterDate(wStart, wEnd))
        .map((im) => im.set('diff', im.date().difference(start, 'day').abs()))
        .sort('diff');
      const altSize = await ev(altCol.size());
      if (altSize === 0) {
        return { status: 'C1', terraSize, aquaSize, usedInfo: 'No images ±1d' };
      }
      const nearest = ee.Image(altCol.first());
      img = nearest.select('NDSI_Snow_Cover');
      const usedDate = await ev(nearest.date().format('YYYY-MM-dd'));
      usedInfo = `Fallback:${usedDate}`;
      return { status: 'OK', img, terraSize, aquaSize, usedInfo };
    } else {
      // Combine Terra and Aqua same-day via per-pixel max to reduce cloud gaps
      let images = [];
      if (terraSize > 0) images.push(ee.Image(terraCol.first()).select('NDSI_Snow_Cover'));
      if (aquaSize > 0) images.push(ee.Image(aquaCol.first()).select('NDSI_Snow_Cover'));
      img = images.length === 2 ? ee.ImageCollection(images).max() : images[0];
      return { status: 'OK', img, terraSize, aquaSize, usedInfo };
    }
  }

  async function computeStats(dateStr) {
    const built = await buildImageForDate(dateStr);
    if (built.status !== 'OK') return built;

    const img = built.img;
    // Valid range mask (0..100)
    const validMask = img.gte(0).and(img.lte(100));
    const validImg = img.updateMask(validMask).select('NDSI_Snow_Cover');

    // Counts at 1 km scale
    const scale = 1000;
    const maxPixels = 1e9;

    // Total possible pixels in region at scale
    const ones = ee.Image(1).rename('ones');
    const totalDict = ones.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    });
    const totalPossible = (await ev(totalDict)).ones || 0;

    const validDict = validImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    });
    const validCount = (await ev(validDict))['NDSI_Snow_Cover'] || 0;

    if (!totalPossible || validCount === 0) {
      return {
        status: validCount === 0 ? 'C2' : 'C3',
        terraSize: built.terraSize,
        aquaSize: built.aquaSize,
        usedInfo: built.usedInfo,
        totalPossible,
        validCount
      };
    }

    // Snow pixels: NDSI_Snow_Cover >= 50 within valid pixels
    const snowMask = validImg.gte(50);
    const snowOnes = ee.Image(1).updateMask(snowMask).rename('ones');
    const snowDict = snowOnes.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: scale,
      maxPixels: maxPixels
    });
    const snowCount = (await ev(snowDict)).ones || 0;

    const snowPct = (snowCount / validCount) * 100.0;
    const cloudPct = ((totalPossible - validCount) / totalPossible) * 100.0;

    if (
      snowPct === null ||
      isNaN(snowPct) ||
      !isFinite(snowPct) ||
      snowPct < 0 ||
      snowPct > 100
    ) {
      return { status: 'C3', terraSize: built.terraSize, aquaSize: built.aquaSize, usedInfo: built.usedInfo };
    }

    return {
      status: 'OK',
      terraSize: built.terraSize,
      aquaSize: built.aquaSize,
      usedInfo: built.usedInfo,
      validCount,
      snowCount,
      totalPossible,
      snowPct,
      cloudPct
    };
  }

  try {
    const s2021 = await computeStats(dates[0]);
    const s2023 = await computeStats(dates[1]);

    // Print concise evidence (max 20 lines)
    if (s2021.status === 'C1' || s2023.status === 'C1') {
      console.log(`2021 MODIS Terra/Aqua: ${s2021.terraSize || 0}/${s2021.aquaSize || 0}`);
      console.log(`2023 MODIS Terra/Aqua: ${s2023.terraSize || 0}/${s2023.aquaSize || 0}`);
      console.log('C1');
      return;
    }
    if (s2021.status === 'C2' || s2023.status === 'C2') {
      console.log(`2021 Valid Pixels: ${s2021.validCount || 0}/${s2021.totalPossible || 0}`);
      console.log(`2023 Valid Pixels: ${s2023.validCount || 0}/${s2023.totalPossible || 0}`);
      console.log('C2');
      return;
    }
    if (s2021.status === 'C3' || s2023.status === 'C3') {
      console.log('C3');
      return;
    }

    console.log(`2021-12-18 Terra/Aqua imgs: ${s2021.terraSize}/${s2021.aquaSize} (${s2021.usedInfo})`);
    console.log(
      `2021 Valid: ${s2021.validCount}, Snow: ${s2021.snowCount}, Snow%: ${s2021.snowPct.toFixed(
        2
      )}, Invalid%: ${s2021.cloudPct.toFixed(1)}`
    );

    console.log(`2023-12-18 Terra/Aqua imgs: ${s2023.terraSize}/${s2023.aquaSize} (${s2023.usedInfo})`);
    console.log(
      `2023 Valid: ${s2023.validCount}, Snow: ${s2023.snowCount}, Snow%: ${s2023.snowPct.toFixed(
        2
      )}, Invalid%: ${s2023.cloudPct.toFixed(1)}`
    );

    const diff = s2023.snowPct - s2021.snowPct;
    console.log(`Change (2023-2021): ${diff.toFixed(2)} pp`);

    // Final decision
    if (!isFinite(diff)) {
      console.log('C3');
    } else if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
